(n, m) = map(int, input().split())
teleporters = list(map(int, input().split()))
paths = []
for i in range(n):
	paths.append([])
for i in range(n - 1):
	(a, b) = map(lambda x: int(x) - 1, input().split())
	if not paths[a]:
		paths[b].append([a, b])
	for path in paths[a]:
		paths[b].append(path + [b])
for i in range(m):
	inp = list(map(int, input().split()))
	if inp[0] == 1:
		teleporters[inp[1] - 1] = inp[2]
	else:
		x = inp[1] - 1
		tmp = -1
		for path in paths[x]:
			res = 0
			j = len(path)
			while j > 1:
				j -= teleporters[j - 1]
				res += 1
			if tmp < 0 or tmp > res:
				tmp = res
		print(tmp)
